//! Generates the locale tables consumed by the `hok-i18n` runtime from
//! `locales/*.yml`.
//!
//! YAML is parsed **here and only here**, at build time, so no YAML parser is
//! linked into the release binary. The generated file holds, per locale, a
//! key-sorted slice of `(key, value)` pairs; the runtime binary-searches it.
//!
//! The flattening rules mirror the ones `rust-i18n` used, so the tables are
//! byte-identical to what the previous implementation produced:
//!
//! | YAML node | value written to the table |
//! |---|---|
//! | string | the string |
//! | mapping | recursed into, keys joined with `.` |
//! | null / empty | `""` |
//! | sequence | `""` (e.g. the `cli_alias.*` entries) |
//! | bool / number | their plain textual form |
//!
//! A duplicated key inside one mapping is a hard error here, where the previous
//! parser silently kept the last one — `locales/*.yml` is hand-maintained, so an
//! ambiguous file should fail the build instead of quietly rendering one of two
//! candidate strings.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

fn main() {
    let manifest_dir = PathBuf::from(
        std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR is always set by cargo"),
    );
    // `crates/hok-i18n` -> repository-root `locales/`.
    let locales_dir = manifest_dir.join("../../locales");
    println!("cargo:rerun-if-changed={}", locales_dir.display());

    let mut files = Vec::new();
    for entry in std::fs::read_dir(&locales_dir)
        .unwrap_or_else(|e| panic!("hok-i18n: cannot read {}: {e}", locales_dir.display()))
    {
        let path = entry.expect("readable directory entry").path();
        if matches!(
            path.extension().and_then(|e| e.to_str()),
            Some("yml" | "yaml")
        ) {
            files.push(path);
        }
    }
    files.sort();
    assert!(
        !files.is_empty(),
        "hok-i18n: no locale files found in {}",
        locales_dir.display()
    );

    let mut generated = String::new();
    generated
        .push_str("// @generated by crates/hok-i18n/build.rs from locales/*.yml -- do not edit.\n");
    generated.push_str("/// Locale name and its flattened, key-sorted `key -> value` table.\n");
    generated.push_str("pub static LOCALES: &[(&str, &[(&str, &str)])] = &[\n");

    for file in &files {
        println!("cargo:rerun-if-changed={}", file.display());
        let locale = file
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or_else(|| panic!("hok-i18n: {} has no file stem", file.display()));
        let source = std::fs::read_to_string(file)
            .unwrap_or_else(|e| panic!("hok-i18n: cannot read {}: {e}", file.display()));
        let table = flatten_locale(&source, file);
        writeln!(generated, "    ({locale:?}, &[").expect("writing to a String cannot fail");
        for (key, value) in &table {
            writeln!(generated, "        ({key:?}, {value:?}),").expect("String write");
        }
        generated.push_str("    ]),\n");
    }
    generated.push_str("];\n");

    let out_path = Path::new(&std::env::var("OUT_DIR").expect("OUT_DIR is always set by cargo"))
        .join("locales.rs");
    std::fs::write(&out_path, generated)
        .unwrap_or_else(|e| panic!("hok-i18n: cannot write {}: {e}", out_path.display()));
}

/// Parse one locale file and flatten it into `key -> value` pairs.
///
/// Keys are dot-joined paths (`output.done`); the returned map is key-sorted so
/// the runtime can binary-search the generated slice.
fn flatten_locale(source: &str, file: &Path) -> BTreeMap<String, String> {
    let docs = yaml_rust2::YamlLoader::load_from_str(source)
        .unwrap_or_else(|e| panic!("hok-i18n: cannot parse {}: {e}", file.display()));
    let doc = docs
        .first()
        .unwrap_or_else(|| panic!("hok-i18n: {} is empty", file.display()));
    let mut table = BTreeMap::new();
    flatten_node("", doc, &mut table);
    table
}

fn flatten_node(prefix: &str, node: &yaml_rust2::Yaml, out: &mut BTreeMap<String, String>) {
    match node {
        yaml_rust2::Yaml::Hash(mapping) => {
            for (key, value) in mapping {
                let Some(key) = key.as_str() else {
                    panic!("hok-i18n: non-string mapping key under {prefix:?}");
                };
                let path = if prefix.is_empty() {
                    key.to_string()
                } else {
                    format!("{prefix}.{key}")
                };
                flatten_node(&path, value, out);
            }
        }
        // A sequence has no single string form; rust-i18n collapsed it to the
        // empty string, which is what the `cli_alias.*` entries rely on.
        yaml_rust2::Yaml::Array(_) | yaml_rust2::Yaml::Null => {
            out.insert(prefix.to_string(), String::new());
        }
        yaml_rust2::Yaml::String(text) => {
            out.insert(prefix.to_string(), text.clone());
        }
        yaml_rust2::Yaml::Boolean(value) => {
            out.insert(prefix.to_string(), value.to_string());
        }
        yaml_rust2::Yaml::Integer(value) => {
            out.insert(prefix.to_string(), value.to_string());
        }
        // `Real` carries the scalar's source text (`1.5` stays `1.5`, matching
        // the newline-free stringification rust-i18n produced).
        yaml_rust2::Yaml::Real(value) => {
            out.insert(prefix.to_string(), value.clone());
        }
        // Anchors/aliases and incoherent scalars are rejected rather than
        // guessed at: the locale files are plain mappings of strings, so
        // anything else is a mistake the build should surface.
        yaml_rust2::Yaml::Alias(_) | yaml_rust2::Yaml::BadValue => {
            panic!("hok-i18n: unsupported YAML node under {prefix:?}");
        }
    }
}
